#!/usr/bin/env bash
# Reproduce the real-validation numbers of 's4' (model-lumpi-track/routed-g4) from the checkpoints: realval-A/B inference of every used
# member with its committed post-processing, bag fusion, merge with model.yaml, official metric, comparison with
# validation/results/scorecard.json. Needs the prepared real validation data and the checkpoints. Generated by
# common/tools/reproduce_validation.py. Run on an idle GPU:
#   CUDA_VISIBLE_DEVICES=0 bash model-lumpi-track/routed-g4/test/reproduce_s4_validation.sh
# The inference commands are independent: `python common/tools/reproduce_validation.py model-lumpi-track/routed-g4 --tag s4 --jobs`
# prints them, one per line, for running several GPUs at once.
set -euo pipefail
cd "$(dirname "${BASH_SOURCE[0]}")/../../.."      # the repository root (portable)
source common/env/activate.sh
mkdir -p model-lumpi-track/routed-g4/validation/output/repro_s4
[ -s model-lumpi-track/routed-g4/validation/output/repro_s4/centerpoint-g1v3_tta_val.json ] || python common/tools/pcdet_predict.py model-lumpi-track/centerpoint-g1v3 --ckpt model-lumpi-track/centerpoint-g1v3/train/output/pcdet_model/run1/ckpt/checkpoint_epoch_40.pth --frames pcdet/realval-v1 --split val --postprocess model-lumpi-track/centerpoint-g1v3/test/postprocess_tta.yaml --tta flip4+yaw+z --out model-lumpi-track/routed-g4/validation/output/repro_s4/centerpoint-g1v3_tta_val.json
[ -s model-lumpi-track/routed-g4/validation/output/repro_s4/centerpoint-g1v3_tta_valB.json ] || python common/tools/pcdet_predict.py model-lumpi-track/centerpoint-g1v3 --ckpt model-lumpi-track/centerpoint-g1v3/train/output/pcdet_model/run1/ckpt/checkpoint_epoch_40.pth --frames pcdet/realval-v1 --split valB --postprocess model-lumpi-track/centerpoint-g1v3/test/postprocess_tta.yaml --tta flip4+yaw+z --out model-lumpi-track/routed-g4/validation/output/repro_s4/centerpoint-g1v3_tta_valB.json
[ -s model-lumpi-track/routed-g4/validation/output/repro_s4/pointpillars-g1_val.json ] || python common/tools/pcdet_predict.py model-lumpi-track/pointpillars-g1 --ckpt model-lumpi-track/pointpillars-g1/train/output/pcdet_model/run1/ckpt/checkpoint_epoch_40.pth --frames pcdet/realval-v1 --split val --postprocess model-lumpi-track/pointpillars-g1/test/postprocess.yaml --out model-lumpi-track/routed-g4/validation/output/repro_s4/pointpillars-g1_val.json
[ -s model-lumpi-track/routed-g4/validation/output/repro_s4/pointpillars-g1_valB.json ] || python common/tools/pcdet_predict.py model-lumpi-track/pointpillars-g1 --ckpt model-lumpi-track/pointpillars-g1/train/output/pcdet_model/run1/ckpt/checkpoint_epoch_40.pth --frames pcdet/realval-v1 --split valB --postprocess model-lumpi-track/pointpillars-g1/test/postprocess.yaml --out model-lumpi-track/routed-g4/validation/output/repro_s4/pointpillars-g1_valB.json
[ -s model-lumpi-track/routed-g4/validation/output/repro_s4/pointpillars-g1_tta_val.json ] || python common/tools/pcdet_predict.py model-lumpi-track/pointpillars-g1 --ckpt model-lumpi-track/pointpillars-g1/train/output/pcdet_model/run1/ckpt/checkpoint_epoch_40.pth --frames pcdet/realval-v1 --split val --postprocess model-lumpi-track/pointpillars-g1/test/postprocess_tta.yaml --tta flip4+yaw+z --out model-lumpi-track/routed-g4/validation/output/repro_s4/pointpillars-g1_tta_val.json
[ -s model-lumpi-track/routed-g4/validation/output/repro_s4/pointpillars-g1_tta_valB.json ] || python common/tools/pcdet_predict.py model-lumpi-track/pointpillars-g1 --ckpt model-lumpi-track/pointpillars-g1/train/output/pcdet_model/run1/ckpt/checkpoint_epoch_40.pth --frames pcdet/realval-v1 --split valB --postprocess model-lumpi-track/pointpillars-g1/test/postprocess_tta.yaml --tta flip4+yaw+z --out model-lumpi-track/routed-g4/validation/output/repro_s4/pointpillars-g1_tta_valB.json
[ -s model-lumpi-track/routed-g4/validation/output/repro_s4/pointpillars-g1v3_val.json ] || python common/tools/pcdet_predict.py model-lumpi-track/pointpillars-g1v3 --ckpt model-lumpi-track/pointpillars-g1v3/train/output/pcdet_model/run1/ckpt/checkpoint_epoch_40.pth --frames pcdet/realval-v1 --split val --postprocess model-lumpi-track/pointpillars-g1v3/test/postprocess.yaml --out model-lumpi-track/routed-g4/validation/output/repro_s4/pointpillars-g1v3_val.json
[ -s model-lumpi-track/routed-g4/validation/output/repro_s4/pointpillars-g1v3_valB.json ] || python common/tools/pcdet_predict.py model-lumpi-track/pointpillars-g1v3 --ckpt model-lumpi-track/pointpillars-g1v3/train/output/pcdet_model/run1/ckpt/checkpoint_epoch_40.pth --frames pcdet/realval-v1 --split valB --postprocess model-lumpi-track/pointpillars-g1v3/test/postprocess.yaml --out model-lumpi-track/routed-g4/validation/output/repro_s4/pointpillars-g1v3_valB.json
[ -s model-lumpi-track/routed-g4/validation/output/repro_s4/pointpillars-g1v3_tta_val.json ] || python common/tools/pcdet_predict.py model-lumpi-track/pointpillars-g1v3 --ckpt model-lumpi-track/pointpillars-g1v3/train/output/pcdet_model/run1/ckpt/checkpoint_epoch_40.pth --frames pcdet/realval-v1 --split val --postprocess model-lumpi-track/pointpillars-g1v3/test/postprocess_tta.yaml --tta flip4+yaw+z --out model-lumpi-track/routed-g4/validation/output/repro_s4/pointpillars-g1v3_tta_val.json
[ -s model-lumpi-track/routed-g4/validation/output/repro_s4/pointpillars-g1v3_tta_valB.json ] || python common/tools/pcdet_predict.py model-lumpi-track/pointpillars-g1v3 --ckpt model-lumpi-track/pointpillars-g1v3/train/output/pcdet_model/run1/ckpt/checkpoint_epoch_40.pth --frames pcdet/realval-v1 --split valB --postprocess model-lumpi-track/pointpillars-g1v3/test/postprocess_tta.yaml --tta flip4+yaw+z --out model-lumpi-track/routed-g4/validation/output/repro_s4/pointpillars-g1v3_tta_valB.json
[ -s model-lumpi-track/routed-g4/validation/output/repro_s4/pvrcnnpp-g1v3_tta_val.json ] || python common/tools/pcdet_predict.py model-lumpi-track/pvrcnnpp-g1v3 --ckpt model-lumpi-track/pvrcnnpp-g1v3/train/output/pcdet_model/run1/ckpt/checkpoint_epoch_40.pth --frames pcdet/realval-v1 --split val --postprocess model-lumpi-track/pvrcnnpp-g1v3/test/postprocess_tta.yaml --tta flip4+yaw+z --out model-lumpi-track/routed-g4/validation/output/repro_s4/pvrcnnpp-g1v3_tta_val.json
[ -s model-lumpi-track/routed-g4/validation/output/repro_s4/pvrcnnpp-g1v3_tta_valB.json ] || python common/tools/pcdet_predict.py model-lumpi-track/pvrcnnpp-g1v3 --ckpt model-lumpi-track/pvrcnnpp-g1v3/train/output/pcdet_model/run1/ckpt/checkpoint_epoch_40.pth --frames pcdet/realval-v1 --split valB --postprocess model-lumpi-track/pvrcnnpp-g1v3/test/postprocess_tta.yaml --tta flip4+yaw+z --out model-lumpi-track/routed-g4/validation/output/repro_s4/pvrcnnpp-g1v3_tta_valB.json
[ -s model-lumpi-track/routed-g4/validation/output/repro_s4/voxelrcnn-g1v3_tta_val.json ] || python common/tools/pcdet_predict.py model-lumpi-track/voxelrcnn-g1v3 --ckpt model-lumpi-track/voxelrcnn-g1v3/train/output/pcdet_model/run1/ckpt/checkpoint_epoch_40.pth --frames pcdet/realval-v1 --split val --postprocess model-lumpi-track/voxelrcnn-g1v3/test/postprocess_tta.yaml --tta flip4+yaw+z --out model-lumpi-track/routed-g4/validation/output/repro_s4/voxelrcnn-g1v3_tta_val.json
[ -s model-lumpi-track/routed-g4/validation/output/repro_s4/voxelrcnn-g1v3_tta_valB.json ] || python common/tools/pcdet_predict.py model-lumpi-track/voxelrcnn-g1v3 --ckpt model-lumpi-track/voxelrcnn-g1v3/train/output/pcdet_model/run1/ckpt/checkpoint_epoch_40.pth --frames pcdet/realval-v1 --split valB --postprocess model-lumpi-track/voxelrcnn-g1v3/test/postprocess_tta.yaml --tta flip4+yaw+z --out model-lumpi-track/routed-g4/validation/output/repro_s4/voxelrcnn-g1v3_tta_valB.json
python common/tools/reproduce_validation.py model-lumpi-track/routed-g4 --tag s4 --score
